method.description:
Calls [param step] again and again, a slice of the work each time, until it returns [code]false[/code] (or anything but [code]true[/code]) or its object is freed. Each frame it gets [param budget_ms] milliseconds, six times that while [member screen_hidden] is on, and the rest waits for the next frame. Its time is measured as [param what].
[codeblock]
var waiting: Array[Node3D] = []

func _make_solid() -> bool:
    add_collision(waiting.pop_back())
    return not waiting.is_empty()

func _ready() -> void:
    FrameBudget.spread("collision", _make_solid)
[/codeblock]
